package com.crowdalarm;

/**
 * The two ways the plugin can alert. The settings panel shows {@link #toString()}.
 */
public enum AlertMode
{
	/** That many NEW players appeared within a few seconds while the player stood still. */
	ARRIVE("Players arrive together"),
	/** That many players are on screen (it was fewer on the tick before). */
	ON_SCREEN("Players on screen");

	private final String text;

	AlertMode(String text)
	{
		this.text = text;
	}

	@Override
	public String toString()
	{
		return text;
	}
}

package com.crowdalarm;

import net.runelite.client.config.FlashNotification;
import net.runelite.client.config.Notification;
import net.runelite.client.config.NotificationSound;
import net.runelite.client.config.RequestFocusType;

/**
 * Builds RuneLite's own notification for an alert from the Sound tick, so the player never opens RuneLite's
 * notification panel. The sound is RuneLite's own alert sound (its "custom" sound: the player's own notification.wav
 * when there is one, else the one RuneLite ships), played through RuneLite's audio player; the "native" choice is the
 * operating system's default beep, which on many Windows set-ups is silent. RuneLite's flash and desktop pop-up stay
 * off: the plugin draws its own smooth flash ({@link FlashPulse}), and the pop-up was dropped. Every field RuneLite
 * reads for this is set: it reads a notification's own fields only when it is marked both "override" and
 * "initialized", a bare one leaves the sound, flash and focus fields empty, and without "send when focused" RuneLite
 * stays silent while the game window is in front. Plain Java.
 */
final class AlertSignal
{
	/** RuneLite's alert sound at full volume (the player's computer volume still applies). */
	static final int VOLUME = 100;

	private AlertSignal()
	{
	}

	/**
	 * @return the notification to hand RuneLite's {@code Notifier}. It is enabled even with the sound off, so RuneLite
	 * still tells any other plugin that listens for notifications; it then does nothing the player hears or sees.
	 */
	static Notification of(boolean sound)
	{
		return Notification.ON
			.withInitialized(true)
			.withOverride(true)
			.withSendWhenFocused(true)
			.withTray(false)
			.withRequestFocus(RequestFocusType.OFF)
			.withSound(sound ? NotificationSound.CUSTOM : NotificationSound.OFF)
			.withVolume(VOLUME)
			.withGameMessage(false)
			.withFlash(FlashNotification.DISABLED);
	}
}

package com.crowdalarm;

/**
 * The words a player reads: the alert and the count box.
 */
final class AlertText
{
	private AlertText()
	{
	}

	/**
	 * The alert text. It starts with the alert's own name from the settings, so the player can tell which alert went
	 * off: {@code 2h Crowd Alarm: crowd size reached, 23 players nearby.} or
	 * {@code 2h Crowd Alarm: sudden crowd, 23 players arrived.}
	 */
	static String of(AlertMode mode, int n)
	{
		return "2h Crowd Alarm: " + (mode == AlertMode.ARRIVE ? "sudden crowd, " : "crowd size reached, ") + n
			+ (n == 1 ? " player" : " players") + (mode == AlertMode.ARRIVE ? " arrived." : " nearby.");
	}

	/** The text when the crowd leaves, for example {@code 2h Crowd Alarm: the crowd left, 12 players nearby.} */
	static String left(int n)
	{
		return "2h Crowd Alarm: the crowd left, " + n + (n == 1 ? " player" : " players") + " nearby.";
	}

	/** The count box's progress line, for example {@code Arrived: 7/20}. */
	static String progress(int arrived, int players)
	{
		return "Arrived: " + arrived + "/" + players;
	}

	/** The count box's one line, for example {@code Players: 23}. */
	static String count(int n)
	{
		return "Players: " + n;
	}
}

package com.crowdalarm;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Path2D;

/**
 * The 2hBuilds coin, the family mark every 2hBuilds plugin carries in the top-left corner of its sidebar icon: a
 * hammered gold disc 9 px across with its "2h" struck in dark brown, drawn in code so it needs no image file. It is
 * the coin half of {@link NavIcon}, pulled out so the one picture can be copied into another plugin's package
 * unchanged - it refers to nothing of this plugin's and to no class but the JDK's.
 *
 * <p>{@link #paint} draws it where it sits in a 16 x 16 icon, the disc centred on (4.5, 4.5): three jittered discs
 * with antialiasing on, then the two letters crisp on top, antialiasing off again, so a caller that draws more on
 * the same {@link Graphics2D} afterwards gets the hint it had not set itself.
 */
final class CoinGlyph
{
	private static final Color RIM = new Color(88, 62, 16);
	private static final Color EDGE = new Color(140, 102, 30);
	private static final Color FACE = new Color(196, 156, 58);
	private static final Color INK = new Color(52, 36, 8);

	/** The coin's centre and the three radii of its rim, edge and face. */
	private static final double COIN_X = 4.5, COIN_Y = 4.5;
	private static final double[] RADII = {4.7, 3.9, 3.3};
	private static final Color[] RINGS = {RIM, EDGE, FACE};
	/** The hammering: one offset per sixteenth of the edge. */
	private static final double[] JITTER = {0.3, -0.2, 0.4, 0.1, -0.3, 0.2, 0.4, -0.1, 0.2, -0.4, 0.3, 0.0, -0.3, 0.4, -0.1, 0.2};

	/** The letters, one character a pixel: "2" then "h", 3 wide and 5 tall each, a 1 px gap between. */
	private static final String[] TWO = {"###", "..#", "###", "#..", "###"};
	private static final String[] H = {"#..", "#..", "###", "#.#", "#.#"};
	private static final int LETTERS_X = 1, LETTERS_Y = 2;

	private CoinGlyph()
	{
	}

	/**
	 * Draws the coin in the top-left of the 16 x 16 icon {@code g} paints on: three jittered discs with
	 * antialiasing, then the letters crisp on top. Leaves the antialiasing hint off and the colour at the letters'
	 * ink.
	 */
	static void paint(Graphics2D g)
	{
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		for (int i = 0; i < RADII.length; i++)
		{
			g.setColor(RINGS[i]);
			g.fill(coin(RADII[i]));
		}
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
		glyph(g, TWO, LETTERS_X, LETTERS_Y);
		glyph(g, H, LETTERS_X + 4, LETTERS_Y);
	}

	private static Path2D coin(double radius)
	{
		final Path2D path = new Path2D.Double();
		for (int i = 0; i < JITTER.length; i++)
		{
			final double angle = i * Math.PI * 2 / JITTER.length;
			final double r = radius + JITTER[i];
			final double x = COIN_X + Math.cos(angle) * r;
			final double y = COIN_Y + Math.sin(angle) * r;
			if (i == 0)
			{
				path.moveTo(x, y);
			}
			else
			{
				path.lineTo(x, y);
			}
		}
		path.closePath();
		return path;
	}

	private static void glyph(Graphics2D g, String[] rows, int x, int y)
	{
		g.setColor(INK);
		for (int r = 0; r < rows.length; r++)
		{
			for (int c = 0; c < rows[r].length(); c++)
			{
				if (rows[r].charAt(c) == '#')
				{
					g.fillRect(x + c, y + r, 1, 1);
				}
			}
		}
	}
}

package com.crowdalarm;

import java.awt.Color;

/**
 * The colour of the count box's border. It shows the live count only: it is not an alert, so "Wait between alerts"
 * never holds it back. Plain Java.
 */
final class CountBorder
{
	private CountBorder()
	{
	}

	/**
	 * @param on whether "Gold border at crowd size" is ticked
	 * @return the at-or-above colour once the count has reached the crowd size, the below colour under it, or null for
	 * no border
	 */
	static Color colour(boolean on, int count, int players, Color above, Color below)
	{
		if (!on)
		{
			return null;
		}
		return count >= players ? above : below;
	}
}

package com.crowdalarm;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Stroke;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;

/**
 * The small movable box with the number of counted players. It decides in {@code render} whether to show. With "Gold
 * border at crowd size" ticked its border shows the live count: one colour at or above the crowd size, another below
 * it.
 */
class CountOverlay extends OverlayPanel
{
	private final CrowdAlarmPlugin plugin;
	private final CrowdAlarmConfig config;

	@Inject
	CountOverlay(CrowdAlarmPlugin plugin, CrowdAlarmConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		final int count = plugin.getShownCount();
		if (!config.showCount() || count < 0)
		{
			return null;
		}
		panelComponent.getChildren().add(LineComponent.builder()
			.left(AlertText.count(count))
			.leftColor(Color.WHITE)
			.build());
		final int arrived = plugin.getShownArrived();
		if (config.showProgress() && config.arrive() && arrived >= 0)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left(AlertText.progress(arrived, config.arrivePlayers()))
				.build());
		}
		final Dimension size = super.render(graphics);

		final Color border = CountBorder.colour(config.crowdBorder(), count, config.players(), config.borderAbove(),
			config.borderBelow());
		if (size != null && border != null)
		{
			final Stroke oldStroke = graphics.getStroke();
			final Color oldColor = graphics.getColor();
			graphics.setStroke(new BasicStroke(2f));
			graphics.setColor(border);
			graphics.drawRect(1, 1, size.width - 3, size.height - 3);
			graphics.setStroke(oldStroke);
			graphics.setColor(oldColor);
		}
		return size;
	}
}

package com.crowdalarm;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

/**
 * The plugin's settings. Flat on purpose: every item is declared here and this interface extends {@link Config}
 * alone, because RuneLite stores defaults only for the methods declared on the interface it is given. The group and
 * the keys are frozen at first release; renaming one silently discards every player's setting. There are two alerts,
 * each with its own tick: "Alert at crowd size" (on) when the number of players near you reaches "Crowd size", and,
 * in its own group just below, "Alert on a sudden crowd" (off) when a group of players arrives together, with its own
 * number, "Players arriving". How the player is told, by either alert, is the group after them: a list of plain tick
 * boxes, with no second panel behind a settings icon: the plugin plays RuneLite's own alert sound and draws its own
 * smooth flash, gold unless another colour is picked in Extras. Each hover text says what the setting does and when,
 * in the player's words; the alert ticks all start "When the alert goes off".
 */
@ConfigGroup(CrowdAlarmConfig.GROUP)
public interface CrowdAlarmConfig extends Config
{
	String GROUP = "crowdalarm";

	@ConfigSection(
		name = "Crowd",
		description = "How many players make a crowd, and who counts.",
		position = 1
	)
	String CROWD_SECTION = "crowd";

	@ConfigSection(
		name = "Sudden crowd",
		description = "A second alert, for a group of players arriving together.",
		position = 2
	)
	String SUDDEN_SECTION = "sudden";

	@ConfigSection(
		name = "Alerts",
		description = "How you're told when a crowd gathers.",
		position = 3
	)
	String ALERTS_SECTION = "alerts";

	@ConfigSection(
		name = "Extras",
		description = "More alerts and options.",
		position = 4,
		closedByDefault = true
	)
	String EXTRAS_SECTION = "extras";

	@ConfigItem(
		keyName = "crowdAlert",
		name = "Alert at crowd size",
		description = "Alerts you when the number of players around you reaches your crowd size. "
			+ "The box and its border still work with it off.",
		position = 1,
		section = CROWD_SECTION
	)
	default boolean crowdAlert()
	{
		return true;
	}

	@Range(min = 1, max = 500)
	@ConfigItem(
		keyName = "players",
		name = "Crowd size",
		description = "The alert goes off when this many players are around you.",
		position = 2,
		section = CROWD_SECTION
	)
	default int players()
	{
		return 20;
	}

	@ConfigItem(
		keyName = "area",
		name = "Count",
		description = "Count every player you can see, or only players within How close.",
		position = 3,
		section = CROWD_SECTION
	)
	default SearchArea area()
	{
		return SearchArea.EVERYONE;
	}

	@Range(min = 1, max = 15)
	@ConfigItem(
		keyName = "distance",
		name = "How close (tiles)",
		description = "With Count set to close players, only players this many tiles from you or nearer are counted.",
		position = 4,
		section = CROWD_SECTION
	)
	default int distance()
	{
		return 5;
	}

	@ConfigItem(
		keyName = "arrive",
		name = "Alert on a sudden crowd",
		description = "Alerts you when lots of players arrive within a few seconds, like a group teleporting in, "
			+ "even if it's already busy. Only while you stand still.",
		position = 5,
		section = SUDDEN_SECTION
	)
	default boolean arrive()
	{
		return false;
	}

	@Range(min = 1, max = 500)
	@ConfigItem(
		keyName = "arrivePlayers",
		name = "Players arriving",
		description = "How many players must arrive for the alert. Players already around you don't count.",
		position = 6,
		section = SUDDEN_SECTION
	)
	default int arrivePlayers()
	{
		return 10;
	}

	@Range(min = 1, max = 60)
	@Units(Units.SECONDS)
	@ConfigItem(
		keyName = "withinSeconds",
		name = "Within",
		description = "The players must all arrive within this many seconds.",
		position = 7,
		section = SUDDEN_SECTION
	)
	default int withinSeconds()
	{
		return 5;
	}

	@ConfigItem(
		keyName = "showProgress",
		name = "Show arrivals in the box",
		description = "With the alert on, the box also shows how many have arrived so far, like Arrived: 7/10.",
		position = 8,
		section = SUDDEN_SECTION
	)
	default boolean showProgress()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showCount",
		name = "Show player count",
		description = "Shows a small box with how many players are around you.",
		position = 9,
		section = ALERTS_SECTION
	)
	default boolean showCount()
	{
		return true;
	}

	@ConfigItem(
		keyName = "crowdBorder",
		name = "Gold border at crowd size",
		description = "The box's border turns gold when your crowd size is reached, and grey when there are fewer.",
		position = 10,
		section = ALERTS_SECTION
	)
	default boolean crowdBorder()
	{
		return true;
	}

	@ConfigItem(
		keyName = "chatMessage",
		name = "Chat message",
		description = "When the alert goes off, a message appears in your chat box.",
		position = 11,
		section = ALERTS_SECTION
	)
	default boolean chatMessage()
	{
		return true;
	}

	@ConfigItem(
		keyName = "sound",
		name = "Sound",
		description = "When the alert goes off, a short alert sound plays.",
		position = 12,
		section = ALERTS_SECTION
	)
	default boolean sound()
	{
		return false;
	}

	@ConfigItem(
		keyName = "flash",
		name = "Flash the screen",
		description = "When the alert goes off, the game screen flashes gold for 2 seconds.",
		position = 13,
		section = ALERTS_SECTION
	)
	default boolean flash()
	{
		return false;
	}

	@Range(min = 0, max = 600)
	@Units(Units.SECONDS)
	@ConfigItem(
		keyName = "cooldownSeconds",
		name = "Wait between alerts",
		description = "After an alert, no new alert for this long. The border still changes straight away.",
		position = 14,
		section = ALERTS_SECTION
	)
	default int cooldownSeconds()
	{
		return 30;
	}

	@ConfigItem(
		keyName = "ignoreFriends",
		name = "Ignore friends",
		description = "Players on your friends list aren't counted.",
		position = 15,
		section = EXTRAS_SECTION
	)
	default boolean ignoreFriends()
	{
		return false;
	}

	@ConfigItem(
		keyName = "ignoreClan",
		name = "Ignore clan",
		description = "Members of your clan aren't counted.",
		position = 16,
		section = EXTRAS_SECTION
	)
	default boolean ignoreClan()
	{
		return false;
	}

	@ConfigItem(
		keyName = "crowdLeft",
		name = "Tell me when the crowd leaves",
		description = "Also alerts you when the number of players drops back below your crowd size.",
		position = 17,
		section = EXTRAS_SECTION
	)
	default boolean crowdLeft()
	{
		return false;
	}

	@ConfigItem(
		keyName = "testAlert",
		name = "Test alert",
		description = "Tick it to see and hear your alert right now. It unticks itself.",
		position = 18,
		section = EXTRAS_SECTION
	)
	default boolean testAlert()
	{
		return false;
	}

	@ConfigItem(
		keyName = "borderAbove",
		name = "Border colour, at or above",
		description = "The border colour when your crowd size is reached.",
		position = 19,
		section = EXTRAS_SECTION
	)
	default Color borderAbove()
	{
		return new Color(196, 156, 58);
	}

	@ConfigItem(
		keyName = "borderBelow",
		name = "Border colour, below",
		description = "The border colour when there are fewer players than your crowd size.",
		position = 20,
		section = EXTRAS_SECTION
	)
	default Color borderBelow()
	{
		return new Color(120, 120, 120);
	}

	@ConfigItem(
		keyName = "flashColour",
		name = "Flash colour",
		description = "The colour the screen flashes when the alert goes off. Flash the screen must be ticked.",
		position = 21,
		section = EXTRAS_SECTION
	)
	default Color flashColour()
	{
		return new Color(196, 156, 58);
	}
}

package com.crowdalarm;

import com.google.inject.Provides;
import java.util.HashSet;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.RuneLiteProperties;
import net.runelite.client.Notifier;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * 2h Crowd Alarm: every game tick it counts the other players the client shows and says when a crowd has arrived or
 * gathered: a chat line and, as the player ticks them, RuneLite's own alert sound and a smooth gold flash over the
 * screen. It is off in the Wilderness and on PvP worlds. It reads only what the client already shows, keeps names for one tick to
 * tell what is new, and never marks or tracks anyone.
 */
@PluginDescriptor(
	name = "2h Crowd Alarm",
	internalName = "crowd-alarm",
	description = "Never miss the boat: an alert when the crowd is back for Pest Control, Tempoross and other minigames. Off in the Wilderness and on PvP worlds. (v" + Version.CURRENT + ")",
	tags = {"players", "crowd", "alarm", "alert", "notification", "pest control", "tempoross", "minigame", "boat", "afk",
		"player count"}
)
public class CrowdAlarmPlugin extends Plugin
{
	private static final Logger log = LoggerFactory.getLogger(CrowdAlarmPlugin.class);

	/** Settings that only change how an alert looks or sounds: changing one makes the alarms forget nothing. */
	private static final Set<String> LOOK_ONLY_KEYS = Set.of("showCount", "crowdBorder", "chatMessage", "sound",
		"flash", "showProgress", "crowdLeft", "borderAbove", "borderBelow", "flashColour");

	@Inject
	private Client client;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ClientThread clientThread;

	@Inject
	private Notifier notifier;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private CountOverlay overlay;

	@Inject
	private RangeOverlay rangeOverlay;

	@Inject
	private ScreenFlashOverlay flashOverlay;

	@Inject
	private CrowdAlarmConfig config;

	/**
	 * The alarm for "this many players are near you". It ticks always, so the crowd leaving is still seen and whether
	 * the crowd is there stays current, but it alerts only while "Alert at crowd size" is on; switching that on starts
	 * it afresh. Used only on the client thread.
	 */
	private CrowdWatch nearbyWatch = new CrowdWatch();

	/**
	 * The alarm for "this many new players arrived together" (the sudden crowd alert, counting to its own number,
	 * "Players arriving"); ticked only while that setting is on.
	 */
	private final CrowdWatch arriveWatch = new CrowdWatch();

	/** When the last alert fired, for the one wait between alerts both alarms share; 0 means never. */
	private long lastAlertMs;

	/** The player's tile on the last tick; null when there is none. */
	private WorldPoint lastTile;

	/** What the count box shows; -1 means nothing to show. */
	private volatile int shownCount = -1;

	/** How many players have arrived in the window, for the progress line; -1 means nothing to show. */
	private volatile int shownArrived = -1;

	/** When the Distance setting last changed (the search-area line fades from then); 0 means never. */
	private volatile long rangeShownAtMs;

	/** When the last alert with "Flash the screen" on fired (the gold pulses run from then); 0 means never. */
	private volatile long flashStartMs;

	@Provides
	CrowdAlarmConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CrowdAlarmConfig.class);
	}

	@Override
	protected void startUp()
	{
		forget();
		rangeShownAtMs = 0;
		flashStartMs = 0;
		lastAlertMs = 0;
		overlayManager.add(overlay);
		overlayManager.add(rangeOverlay);
		overlayManager.add(flashOverlay);
		log.info("2h Crowd Alarm {} started on RuneLite {}", Version.CURRENT, RuneLiteProperties.getVersion());
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(flashOverlay);
		overlayManager.remove(rangeOverlay);
		overlayManager.remove(overlay);
		rangeShownAtMs = 0;
		flashStartMs = 0;
		forget();
	}

	/** What the count box shows; -1 means nothing to show. */
	int getShownCount()
	{
		return shownCount;
	}

	/** How many players have arrived in the window; -1 means nothing to show. */
	int getShownArrived()
	{
		return shownArrived;
	}

	/** When the Distance setting last changed; 0 means never. */
	long getRangeShownAtMs()
	{
		return rangeShownAtMs;
	}

	/** When the last alert with "Flash the screen" on fired; 0 means never. */
	long getFlashStartMs()
	{
		return flashStartMs;
	}

	/**
	 * A counting setting changed: both alarms forget who was there (a wider area is not an arrival), but the crowd
	 * alarm keeps whether the crowd was there, so a crowd that stayed does not alert again.
	 */
	private void countingSettingChanged()
	{
		nearbyWatch.settingsChanged();
		arriveWatch.settingsChanged();
	}

	/**
	 * Back to knowing nothing (login screen, a hop, the plugin starting or stopping, the Wilderness): the box is hidden
	 * and a crowd already there on the next tick alerts once.
	 */
	private void forget()
	{
		nearbyWatch.reset();
		arriveWatch.reset();
		lastTile = null;
		shownCount = -1;
		shownArrived = -1;
	}

	/**
	 * Tells the player: the gold flash when "Flash the screen" is on, RuneLite's own notification with its alert sound
	 * when "Sound" is on (handed over even with the sound off, and sent even while the game window is in front), and the
	 * chat message when it is on.
	 */
	private void alert(String text)
	{
		if (config.flash())
		{
			flashStartMs = System.currentTimeMillis();
		}
		notifier.notify(AlertSignal.of(config.sound()), text);
		if (config.chatMessage() && client.getGameState() == GameState.LOGGED_IN)
		{
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", text, null);
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		final Player local = client.getLocalPlayer();
		final WorldView view = client.getTopLevelWorldView();
		if (local == null || view == null)
		{
			return;
		}

		if (client.getVarbitValue(VarbitID.INSIDE_WILDERNESS) == 1 || PvpWorlds.isPvp(client.getWorldType()))
		{
			forget();
			return;
		}

		final WorldPoint here = local.getWorldLocation();
		final boolean stoodStill = lastTile != null && lastTile.equals(here);
		lastTile = here;

		final Set<String> names = new HashSet<>();
		for (Player player : view.players())
		{
			if (player == local)
			{
				continue;
			}
			final String name = player.getName();
			if (name == null)
			{
				continue;
			}
			final WorldPoint at = player.getWorldLocation();
			if (PlayerFilter.counts(at.getPlane() == here.getPlane(), config.area(), at.distanceTo2D(here),
				config.distance(), player.isFriend(), player.isClanMember(), config.ignoreFriends(),
				config.ignoreClan()))
			{
				names.add(name);
			}
		}
		shownCount = names.size();

		final long now = System.currentTimeMillis();
		final long cooldownMs = config.cooldownSeconds() * 1000L;
		final long withinMs = config.withinSeconds() * 1000L;
		final int nearby = nearbyWatch.tick(names, stoodStill, now, AlertMode.ON_SCREEN, config.players(), withinMs,
			cooldownMs);
		final int reached = config.crowdAlert() ? nearby : 0;
		int arrived = 0;
		if (config.arrive())
		{
			arrived = arriveWatch.tick(names, stoodStill, now, AlertMode.ARRIVE, config.arrivePlayers(), withinMs,
				cooldownMs);
			shownArrived = arriveWatch.arrivedSoFar();
		}
		else
		{
			shownArrived = -1;
		}
		// Both alarms can fire on one tick: the player is told once, in the words of the arrival, which says more.
		final int n = arrived > 0 ? arrived : reached;
		if (n > 0 && (lastAlertMs == 0 || now - lastAlertMs >= cooldownMs))
		{
			final AlertMode mode = arrived > 0 ? AlertMode.ARRIVE : AlertMode.ON_SCREEN;
			lastAlertMs = now;
			alert(AlertText.of(mode, n));
			log.debug("alert: mode {}, number {}, counted {}", mode, n, names.size());
		}
		if (config.crowdLeft() && nearbyWatch.crowdLeft())
		{
			alert(AlertText.left(names.size()));
			log.debug("crowd left: counted {}", names.size());
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
		{
			forget();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!CrowdAlarmConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		final String key = event.getKey();
		if ("testAlert".equals(key))
		{
			if (Boolean.parseBoolean(event.getNewValue()))
			{
				// The settings panel posts this on the Swing thread; the alert belongs to the client thread.
				clientThread.invoke(() -> alert(config.arrive()
					? AlertText.of(AlertMode.ARRIVE, config.arrivePlayers())
					: AlertText.of(AlertMode.ON_SCREEN, config.players())));
				configManager.setConfiguration(CrowdAlarmConfig.GROUP, "testAlert", false);
			}
			return;
		}
		if ("crowdAlert".equals(key))
		{
			if (Boolean.parseBoolean(event.getNewValue()))
			{
				// Switched on: the crowd alarm starts afresh, so a crowd already there alerts once, held back by the wait
				// like any alert. The old one may have seen the crowd come while it was off, and that was no alert.
				clientThread.invoke(() -> nearbyWatch = new CrowdWatch());
			}
			return;
		}
		if (LOOK_ONLY_KEYS.contains(key))
		{
			return;
		}
		if ("distance".equals(key))
		{
			rangeShownAtMs = System.currentTimeMillis();
		}
		// The settings panel posts this on the Swing thread; the watches belong to the client thread.
		clientThread.invoke(this::countingSettingChanged);
	}
}

package com.crowdalarm;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.Iterator;
import java.util.List;
import java.util.Set;

/**
 * Decides, once per game tick, whether a crowd has arrived or gathered. It holds names only to tell what is new since
 * the tick before; nothing is kept about any one player. Plain Java, one instance, used only on the client thread.
 */
final class CrowdWatch
{
	/** How many new players appeared on one tick. */
	private static final class Arrival
	{
		private final long timeMs;
		private final int count;

		private Arrival(long timeMs, int count)
		{
			this.timeMs = timeMs;
			this.count = count;
		}
	}

	/** The previous tick's names; null until a first tick has been recorded. */
	private Set<String> previous;
	private final List<Arrival> arrivals = new ArrayList<>();
	private boolean wasAbove;
	private boolean hasAlerted;
	private long lastAlertMs;
	/** Whether the last tick saw the crowd leave (ON_SCREEN only), see {@link #crowdLeft()}. */
	private boolean left;
	private boolean hasLeft;
	private long lastLeftMs;

	/**
	 * One game tick. A first tick (after a {@link #reset()} or a {@link #settingsChanged()}) records who is there. In
	 * ON_SCREEN mode it also alerts once when the crowd counts as having just been reached: after a reset whether it was
	 * there before is unknown, so a crowd already there alerts (the owner's choice, 2026-11-20); after a settings change
	 * only a count that was below and is now at or above the players does, never a crowd that stayed. The cooldown holds
	 * it back like any alert. In ARRIVE mode a first tick has seen no one arrive, so it only records.
	 *
	 * @param counted    the names counted this tick
	 * @param stoodStill whether the player's own tile is the one it was on the tick before
	 * @param nowMs      the time of this tick
	 * @return the number to put in the alert, or 0 for no alert
	 */
	int tick(Set<String> counted, boolean stoodStill, long nowMs, AlertMode mode, int players, long withinMs,
		long cooldownMs)
	{
		left = false;
		if (previous == null)
		{
			previous = new HashSet<>(counted);
			final boolean above = counted.size() >= players;
			final boolean reached = above && !wasAbove;
			wasAbove = above;
			if (mode != AlertMode.ON_SCREEN || !reached)
			{
				return 0;
			}
			return afterCooldown(counted.size(), nowMs, cooldownMs);
		}

		int fresh = 0;
		for (String name : counted)
		{
			if (!previous.contains(name))
			{
				fresh++;
			}
		}
		previous = new HashSet<>(counted);

		if (!stoodStill)
		{
			arrivals.clear();
		}
		else if (fresh > 0)
		{
			arrivals.add(new Arrival(nowMs, fresh));
		}

		final long oldest = nowMs - withinMs;
		final Iterator<Arrival> it = arrivals.iterator();
		while (it.hasNext())
		{
			if (it.next().timeMs <= oldest)
			{
				it.remove();
			}
		}

		final boolean fire;
		final int number;
		if (mode == AlertMode.ON_SCREEN)
		{
			final boolean above = counted.size() >= players;
			fire = above && !wasAbove;
			if (wasAbove && !above && (!hasLeft || nowMs - lastLeftMs >= cooldownMs))
			{
				left = true;
				hasLeft = true;
				lastLeftMs = nowMs;
			}
			wasAbove = above;
			number = counted.size();
		}
		else
		{
			final int sum = arrivedSoFar();
			fire = sum >= players;
			number = sum;
			if (fire)
			{
				arrivals.clear();
			}
		}

		if (!fire)
		{
			return 0;
		}
		return afterCooldown(number, nowMs, cooldownMs);
	}

	/** @return the number to put in the alert, or 0 while the last alert is within the cooldown; an alert restarts it */
	private int afterCooldown(int number, long nowMs, long cooldownMs)
	{
		if (hasAlerted && nowMs - lastAlertMs < cooldownMs)
		{
			return 0;
		}
		hasAlerted = true;
		lastAlertMs = nowMs;
		return number;
	}

	/** How many new players are in the window right now (what "Players arrive together" adds up). */
	int arrivedSoFar()
	{
		int sum = 0;
		for (Arrival arrival : arrivals)
		{
			sum += arrival.count;
		}
		return sum;
	}

	/**
	 * Whether the last tick saw the crowd leave: in ON_SCREEN mode the count fell from the "Players" number or more to
	 * below it. It is false on a first tick and in ARRIVE mode, and at most once per cooldown.
	 */
	boolean crowdLeft()
	{
		return left;
	}

	/**
	 * After login, a hop, the plugin starting or the Wilderness: forgets the previous names, the arrivals and whether
	 * the crowd was there, so a crowd already there on the next tick counts as just reached. Keeps the last alerts'
	 * times.
	 */
	void reset()
	{
		previous = null;
		arrivals.clear();
		wasAbove = false;
		left = false;
	}

	/**
	 * After a counting setting changes: forgets the previous names and the arrivals (a wider area is not an arrival)
	 * but keeps whether the crowd was there, so a crowd that stayed does not alert again and raising the players over
	 * it is not a leaving. Keeps the last alerts' times.
	 */
	void settingsChanged()
	{
		previous = null;
		arrivals.clear();
		left = false;
	}
}

package com.crowdalarm;

/**
 * The "Flash the screen" alert's timing: two smooth pulses over 2 seconds, timed from the alert itself, so every pulse
 * is the same length. (RuneLite's own flash blinks to the game's clock, so its first blink is cut short by a different
 * amount each time.) The colour is the player's "Flash colour"; this sets only how strong it is. Plain Java.
 */
final class FlashPulse
{
	/** One pulse: from clear up to the strongest colour and back to clear. */
	static final long PULSE_MS = 1_000;

	/** Two pulses. */
	static final long DURATION_MS = 2 * PULSE_MS;

	/** The strongest the colour gets, out of 255: the strength RuneLite uses for its own flash. */
	static final int MAX_ALPHA = 70;

	private FlashPulse()
	{
	}

	/**
	 * @param elapsedMs the time since the alert
	 * @return how strong the colour is now, 0 (clear) to {@link #MAX_ALPHA}: a sine curve squared over each pulse, so
	 * each one starts and ends at clear and has no jumps; 0 before the alert and after the 2 seconds
	 */
	static int alpha(long elapsedMs)
	{
		if (elapsedMs < 0 || elapsedMs >= DURATION_MS)
		{
			return 0;
		}
		final double wave = Math.sin(Math.PI * (elapsedMs % PULSE_MS) / PULSE_MS);
		return (int) Math.round(MAX_ALPHA * wave * wave);
	}
}

package com.crowdalarm;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Line2D;
import java.awt.image.BufferedImage;
import javax.swing.ImageIcon;
import net.runelite.client.ui.ColorScheme;

/**
 * The 2hBuilds settings icon, drawn in code: a ring with eight teeth and a hole through the middle, the picture the
 * settings icon of every 2hBuilds plugin shows (STANDARD A4). It is the bank's icon, pulled out of its widget helper so
 * the one picture can be copied into another plugin unchanged; it refers to no class of the plugin it sits in.
 *
 * <p>The ring is a stroke and not a filled disc, so the middle stays transparent and the picture reads as a settings
 * icon at 12 px rather than as a cogged blob. The teeth are eight round-capped spokes every 45 degrees, starting on
 * the ring's own circle so each is rooted in the ring's metal and none reaches into the hole. Every length is a
 * fraction of the size, so the same shape comes out at any size.
 */
final class GearGlyph
{
	/** The number of teeth. */
	static final int TEETH = 8;
	/** The smallest side drawn: below it the hole closes and the teeth merge. */
	static final int MIN_SIZE = 7;

	private GearGlyph()
	{
	}

	/**
	 * A new square icon, transparent except for the ring and its teeth.
	 *
	 * @param size   the icon's side in px; anything under {@value #MIN_SIZE} is raised to it
	 * @param colour the ink; null falls back to the sidebar's quiet grey, {@link ColorScheme#LIGHT_GRAY_COLOR}
	 */
	static ImageIcon icon(int size, Color colour)
	{
		final int s = Math.max(MIN_SIZE, size);
		final BufferedImage img = new BufferedImage(s, s, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = img.createGraphics();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
			g.setColor(colour == null ? ColorScheme.LIGHT_GRAY_COLOR : colour);
			final double centre = s / 2.0;
			// The ring's centre line, the width of its metal, and how far a tooth's centre line reaches - the last
			// one pulled in by half a tooth so the round cap lands inside the icon instead of being clipped.
			final double ring = centre * 0.52;
			final float ringWidth = (float) Math.max(1.5, s * 0.2);
			final float toothWidth = (float) Math.max(1.3, s * 0.16);
			final double toothOut = centre - toothWidth / 2.0 - 0.25;
			g.setStroke(new BasicStroke(ringWidth, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.draw(new Ellipse2D.Double(centre - ring, centre - ring, ring * 2.0, ring * 2.0));
			g.setStroke(new BasicStroke(toothWidth, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			for (int i = 0; i < TEETH; i++)
			{
				final double angle = i * 2.0 * Math.PI / TEETH;
				final double cos = Math.cos(angle);
				final double sin = Math.sin(angle);
				g.draw(new Line2D.Double(centre + cos * ring, centre + sin * ring,
					centre + cos * toothOut, centre + sin * toothOut));
			}
		}
		finally
		{
			g.dispose();
		}
		return new ImageIcon(img);
	}
}

package com.crowdalarm;

/**
 * Which other players are counted. Plain Java: the plugin reads the game and passes the facts in.
 */
final class PlayerFilter
{
	private PlayerFilter()
	{
	}

	/**
	 * @return true only when the player is on the same plane, inside the search area, and not left out by an
	 * "Ignore" setting
	 */
	static boolean counts(boolean samePlane, SearchArea area, int distance, int maxDistance, boolean isFriend,
		boolean isClan, boolean ignoreFriends, boolean ignoreClan)
	{
		if (!samePlane)
		{
			return false;
		}
		if (area != SearchArea.EVERYONE && distance > maxDistance)
		{
			return false;
		}
		if (ignoreFriends && isFriend)
		{
			return false;
		}
		return !(ignoreClan && isClan);
	}
}

package com.crowdalarm;

import java.util.Collection;
import net.runelite.api.WorldType;

/**
 * Which worlds are PvP worlds. The plugin is always off on them.
 */
final class PvpWorlds
{
	private PvpWorlds()
	{
	}

	/** @return true when the world types hold a PvP world or one of the Deadman, arena, bounty or risk worlds */
	static boolean isPvp(Collection<WorldType> types)
	{
		return WorldType.isPvpWorld(types)
			|| types.contains(WorldType.DEADMAN)
			|| types.contains(WorldType.PVP_ARENA)
			|| types.contains(WorldType.LAST_MAN_STANDING)
			|| types.contains(WorldType.BOUNTY)
			|| types.contains(WorldType.HIGH_RISK);
	}
}

package com.crowdalarm;

/**
 * How visible the search-area line is while it fades after the Distance setting changes. Plain Java.
 */
final class RangeFade
{
	/** The line fades out over this long. */
	static final long DURATION_MS = 3_000;

	private RangeFade()
	{
	}

	/**
	 * @param elapsedMs the time since the setting changed
	 * @return the line's opacity, 255 when it has just appeared down to 0 when it is gone (also 0 for a negative time,
	 * which only a clock set backwards produces)
	 */
	static int alpha(long elapsedMs)
	{
		if (elapsedMs < 0 || elapsedMs >= DURATION_MS)
		{
			return 0;
		}
		return 255 - (int) (255 * elapsedMs / DURATION_MS);
	}
}

package com.crowdalarm;

import java.util.ArrayList;
import java.util.List;

/**
 * The outer edge of the search area: the square of tiles within "Distance" of the player. Plain Java; the overlay turns
 * the points into screen positions.
 */
final class RangeOutline
{
	/** Local units in one tile. */
	static final int TILE = 128;

	private RangeOutline()
	{
	}

	/**
	 * The closed loop around the player's tile, one point at every tile edge, as {x, y} offsets in local units from
	 * the middle of the player's tile. It runs along the south side, the east side, the north side and the west side,
	 * and ends on the point it began on.
	 */
	static List<int[]> loop(int distance)
	{
		final int tiles = 2 * distance + 1;
		final int half = distance * TILE + TILE / 2;
		final List<int[]> points = new ArrayList<>(4 * tiles + 1);
		for (int i = 0; i < tiles; i++)
		{
			points.add(new int[]{-half + i * TILE, -half});
		}
		for (int i = 0; i < tiles; i++)
		{
			points.add(new int[]{half, -half + i * TILE});
		}
		for (int i = 0; i < tiles; i++)
		{
			points.add(new int[]{half - i * TILE, half});
		}
		for (int i = 0; i < tiles; i++)
		{
			points.add(new int[]{-half, half - i * TILE});
		}
		points.add(new int[]{-half, -half});
		return points;
	}
}

package com.crowdalarm;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Stroke;
import java.awt.geom.Path2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * A blue line round the player at the edge of the search area. It shows only for three seconds after the Distance
 * setting changes, fading as it goes, and it follows the player's tile while it shows. It decides in {@code render}.
 */
class RangeOverlay extends Overlay
{
	private static final int BLUE_RED = 0;
	private static final int BLUE_GREEN = 140;
	private static final int BLUE_BLUE = 255;

	private final Client client;
	private final CrowdAlarmPlugin plugin;
	private final CrowdAlarmConfig config;

	@Inject
	RangeOverlay(Client client, CrowdAlarmPlugin plugin, CrowdAlarmConfig config)
	{
		super(plugin);
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		final long shownAt = plugin.getRangeShownAtMs();
		if (shownAt <= 0 || plugin.getShownCount() < 0)
		{
			return null;
		}
		final int alpha = RangeFade.alpha(System.currentTimeMillis() - shownAt);
		final Player local = client.getLocalPlayer();
		if (alpha <= 0 || local == null)
		{
			return null;
		}

		final LocalPoint middle = local.getLocalLocation();
		final int plane = local.getWorldView().getPlane();
		final Path2D.Double path = new Path2D.Double();
		boolean penDown = false;
		for (int[] offset : RangeOutline.loop(config.distance()))
		{
			final LocalPoint edge = new LocalPoint(middle.getX() + offset[0], middle.getY() + offset[1],
				middle.getWorldView());
			final Point screen = Perspective.localToCanvas(client, edge, plane);
			if (screen == null)
			{
				penDown = false;
			}
			else if (penDown)
			{
				path.lineTo(screen.getX(), screen.getY());
			}
			else
			{
				path.moveTo(screen.getX(), screen.getY());
				penDown = true;
			}
		}

		final Stroke oldStroke = graphics.getStroke();
		final Color oldColor = graphics.getColor();
		graphics.setStroke(new BasicStroke(2f));
		graphics.setColor(new Color(BLUE_RED, BLUE_GREEN, BLUE_BLUE, alpha));
		graphics.draw(path);
		graphics.setStroke(oldStroke);
		graphics.setColor(oldColor);
		return null;
	}
}

package com.crowdalarm;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * The "Flash the screen" alert: the whole game screen pulses twice, smoothly, for 2 seconds after an alert
 * ({@link FlashPulse}), in the "Flash colour" (gold unless the player picks another). It draws a see-through colour
 * over the screen and nothing else; the pulse sets how see-through, never the colour picked.
 */
class ScreenFlashOverlay extends Overlay
{
	private final Client client;
	private final CrowdAlarmPlugin plugin;
	private final CrowdAlarmConfig config;

	@Inject
	ScreenFlashOverlay(Client client, CrowdAlarmPlugin plugin, CrowdAlarmConfig config)
	{
		super(plugin);
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ALWAYS_ON_TOP);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		final long startedAt = plugin.getFlashStartMs();
		if (startedAt <= 0)
		{
			return null;
		}
		final int alpha = FlashPulse.alpha(System.currentTimeMillis() - startedAt);
		if (alpha <= 0)
		{
			return null;
		}
		final Color colour = config.flashColour();
		final Color oldColor = graphics.getColor();
		graphics.setColor(new Color(colour.getRed(), colour.getGreen(), colour.getBlue(), alpha));
		graphics.fillRect(0, 0, client.getCanvasWidth(), client.getCanvasHeight());
		graphics.setColor(oldColor);
		return null;
	}
}

package com.crowdalarm;

/**
 * Which players are counted. The settings panel shows {@link #toString()}.
 */
public enum SearchArea
{
	/** Every player the client shows on the player's plane. */
	EVERYONE("Everyone I can see"),
	/** Only players within the "How close" setting of the player. */
	NEARBY("Only players close to me");

	private final String text;

	SearchArea(String text)
	{
		this.text = text;
	}

	@Override
	public String toString()
	{
		return text;
	}
}

package com.crowdalarm;

import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.util.Map;
import java.util.Objects;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Consumer;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.ImageIcon;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import javax.swing.border.Border;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.ImageUtil;

/**
 * Where to find the people behind a 2hBuilds plugin (1.0.9): the support pair in the top-right corner of a card - the
 * Discord mark beside the settings icon - and the settings menu's header, the plugin's name and build over a row of
 * four brand marks (Discord, X, the 2hBuilds GitHub profile and this plugin's own GitHub page). The one place any of it
 * is drawn, and the one place its links are written.
 *
 * <p><b>Written to be copied.</b> This file is the same in every 2hBuilds plugin, with nothing changed but its
 * {@code package} line: it names no class of the plugin it sits in - no panel, no widget helper, no version class,
 * no config - only RuneLite's own ({@link ColorScheme}, {@link FontManager}, {@link ImageUtil}) and the JDK's. What a
 * plugin has to say about itself comes in through the constructor: the name it is shown under, its build, its own
 * GitHub page, what opens a link ({@link net.runelite.client.util.LinkBrowser#browse} in the client, a recorder in
 * a test) and what takes the settings menu down after a link has been pressed. The four mark files are the
 * brands' own, white on transparent and never redrawn, in the resource folder of the copy's package
 * ({@link #markIcon} loads them beside this class).
 *
 * <p>Every hover here is ONE word (or a few) and is always on: an icon with no text beside it has nothing else on
 * the screen to say what it is, so it names itself. Like every other hover in a 2hBuilds plugin it is always on - no
 * plugin of ours has a switch that hides hovers - and it is set on the label directly.
 */
final class SupportLinks
{
	/** Where the Discord mark goes: the 2hBuilds Discord server, opened through the browser hook. */
	static final String DISCORD_URL = "https://discord.gg/nsam4CfWzf";
	/** Where the X mark goes: the 2hBuilds account. */
	static final String X_URL = "https://x.com/2hBuilds";
	/** Where the first GitHub mark goes: the 2hBuilds profile. */
	static final String GITHUB_PROFILE_URL = "https://github.com/2hBuilds";

	/** The settings icon's hover: one word, because the menu under it says the rest. */
	static final String SETTINGS_TIP = "Settings";
	/** The Discord mark's hover: one word. */
	static final String DISCORD_TIP = "Discord";
	/** The X mark's hover in the menu's header: one word. */
	static final String X_TIP = "X";
	/** The first GitHub mark's hover in the menu's header: the 2hBuilds profile. */
	static final String GITHUB_PROFILE_TIP = "2hBuilds on GitHub";
	/** The second GitHub mark's hover in the menu's header: the plugin's own page. */
	static final String GITHUB_TIP = "This plugin on GitHub";

	/** The brand marks' files, in the resource folder of this class's package; see {@link #markIcon}. */
	static final String DISCORD_12 = "discord_12.png";
	static final String DISCORD_16 = "discord_16.png";
	static final String X_16 = "x_16.png";
	static final String GITHUB_16 = "github_16.png";

	/** The gap between the Discord mark and the settings icon on a card, in px. */
	static final int PAIR_GAP = 8;
	/** The gap between two marks in the menu's header row, in px; the marks themselves are 16 px files. */
	static final int LINK_GAP = 6;
	/**
	 * The alpha a brand's mark rests at: 165 of 255, so a white mark reads as the grey 165 the settings icon and the
	 * captions are drawn in ({@link ColorScheme#LIGHT_GRAY_COLOR}).
	 */
	static final float MARK_REST_ALPHA = 165f / 255f;
	/**
	 * The header's version line's grey: a shade darker than the captions' {@link ColorScheme#LIGHT_GRAY_COLOR} (165),
	 * still about 4.6 : 1 against the menu's ground.
	 */
	static final Color HEADER_GREY = new Color(135, 135, 135);
	/** The header's title face: bold, one size up from the menu's 12 px. */
	static final int HEADER_TITLE_SIZE = 13;
	/**
	 * The part of a display name drawn in the brand orange, when the name opens with it and a space: the 2hBuilds mark,
	 * as on the sidebar icon. A name without it is drawn whole in white.
	 */
	static final String FAMILY_MARK = "2h";
	/** The menu's own type size, the version line's. */
	static final int MENU_FONT_SIZE = 12;

	/**
	 * The sidebar's 6 px: the header's left and right padding - the column the captions under it start at - and the
	 * hit area an icon buys on the side the pointer arrives from. {@link #iconBorder} is where the second is written.
	 */
	private static final int INSET = 6;

	/** The marks already loaded, by file name: each PNG is read once (see {@link #markIcon}). */
	private static final Map<String, BufferedImage> MARKS = new ConcurrentHashMap<>();

	private final String displayName;
	private final String version;
	private final String pluginGitHubUrl;
	private final Consumer<String> browser;
	private final Runnable closeMenu;

	/**
	 * @param displayName     the name the plugin is shown under, e.g. "2h Bank Portfolio Tracker"
	 * @param version         the plugin's build, e.g. "1.0.9"; printed as "Version 1.0.9"
	 * @param pluginGitHubUrl the plugin's own repository page, what the fourth mark opens
	 * @param browser         what a pressed mark hands its URL to: RuneLite's {@code LinkBrowser::browse} in the client
	 * @param closeMenu       what takes the settings menu down once a header mark has been pressed, as OK does
	 */
	SupportLinks(String displayName, String version, String pluginGitHubUrl, Consumer<String> browser,
		Runnable closeMenu)
	{
		this.displayName = Objects.requireNonNull(displayName, "displayName");
		this.version = Objects.requireNonNull(version, "version");
		this.pluginGitHubUrl = Objects.requireNonNull(pluginGitHubUrl, "pluginGitHubUrl");
		this.browser = Objects.requireNonNull(browser, "browser");
		this.closeMenu = Objects.requireNonNull(closeMenu, "closeMenu");
	}

	/**
	 * The support pair, the top-right corner of a card: the Discord mark, {@link #PAIR_GAP} px of clear ground, then
	 * {@code settingsIcon} - the settings icon is the right-most thing. The gap is measured between the two ink boxes,
	 * so the strip between the labels is {@link #PAIR_GAP} less the 6 px inset the settings icon carries on its left
	 * ({@link #iconBorder}).
	 *
	 * <p>The pair is as tall as the icons with their 2 px insets, 16 px, and exactly as wide as the two labels and the
	 * strip between them, so a bar that holds it at its east end gives it no more room than that.
	 *
	 * @param settingsIcon the plugin's settings icon, a label carrying {@link #iconBorder}
	 */
	JPanel supportPair(JLabel settingsIcon)
	{
		final JLabel discord = discordMark();
		final JPanel pair = new JPanel();
		pair.setLayout(new BoxLayout(pair, BoxLayout.X_AXIS));
		pair.setOpaque(false);
		pair.add(discord);
		pair.add(Box.createHorizontalStrut(PAIR_GAP - INSET));
		pair.add(settingsIcon);
		final int width = discord.getPreferredSize().width + PAIR_GAP - INSET + settingsIcon.getPreferredSize().width;
		final int height = Math.max(discord.getPreferredSize().height, settingsIcon.getPreferredSize().height);
		pair.setPreferredSize(new Dimension(width, height));
		return pair;
	}

	/**
	 * The Discord mark beside the settings icon: 12 px, with the settings icon's own insets ({@link #iconBorder}), so
	 * the two read as a pair and each has the same 6 px of hit area on the side the pointer arrives from.
	 */
	JLabel discordMark()
	{
		final JLabel mark = brandMark(DISCORD_12, DISCORD_TIP, DISCORD_URL);
		mark.setBorder(iconBorder());
		return mark;
	}

	/**
	 * The settings menu's header: the title line - the family mark in the brand orange and the rest of the display name
	 * in white, both bold at {@link #HEADER_TITLE_SIZE} px, two labels side by side because one label has one colour;
	 * a name that does not open with {@link #FAMILY_MARK} and a space is one white label - over "Version" and the
	 * build in {@link #HEADER_GREY} at the menu's own {@link #MENU_FONT_SIZE} px, over the links row: four 16 px brand
	 * marks, {@link #LINK_GAP} px apart, the Discord mark, the X mark, the GitHub mark for the 2hBuilds profile and the
	 * same GitHub mark for this plugin's own page. Every line at the header's left edge, like the captions below it,
	 * with no hover but the marks' and no click but theirs.
	 *
	 * <p>The two GitHub marks are identical on purpose; only their hovers tell them apart. A press on a mark hands
	 * its URL to the browser and then takes the menu down, the way OK does: a reader who has clicked a link has
	 * finished with the menu. The header is ONE panel, so a menu that holds it counts it as one component.
	 */
	JPanel header()
	{
		final JPanel row = new JPanel(new DynamicGridLayout(0, 1, 0, 0));
		row.setBackground(ColorScheme.DARK_GRAY_COLOR);
		row.setOpaque(false);
		row.setBorder(new EmptyBorder(2, INSET, 2, INSET));
		row.add(titleRow());
		final JLabel versionLine = label("Version " + version, sans(MENU_FONT_SIZE), HEADER_GREY);
		versionLine.setHorizontalAlignment(SwingConstants.LEFT);
		versionLine.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.add(versionLine);
		row.add(linksRow());
		return row;
	}

	/** The header's title line, see {@link #header}. */
	private JPanel titleRow()
	{
		final JPanel title = new JPanel();
		title.setLayout(new BoxLayout(title, BoxLayout.X_AXIS));
		title.setOpaque(false);
		title.setAlignmentX(Component.LEFT_ALIGNMENT);
		if (displayName.startsWith(FAMILY_MARK + " "))
		{
			title.add(label(FAMILY_MARK, sansBold(HEADER_TITLE_SIZE), ColorScheme.BRAND_ORANGE));
			title.add(label(displayName.substring(FAMILY_MARK.length()), sansBold(HEADER_TITLE_SIZE), Color.WHITE));
		}
		else
		{
			title.add(label(displayName, sansBold(HEADER_TITLE_SIZE), Color.WHITE));
		}
		title.add(Box.createHorizontalGlue());
		return title;
	}

	/** The header's links row, see {@link #header}: 2 px of air over it and the marks from the left edge. */
	private JPanel linksRow()
	{
		final JPanel links = new JPanel();
		links.setLayout(new BoxLayout(links, BoxLayout.X_AXIS));
		links.setOpaque(false);
		links.setAlignmentX(Component.LEFT_ALIGNMENT);
		links.setBorder(new EmptyBorder(2, 0, 0, 0));
		addLink(links, DISCORD_16, DISCORD_TIP, DISCORD_URL, false);
		addLink(links, X_16, X_TIP, X_URL, true);
		addLink(links, GITHUB_16, GITHUB_PROFILE_TIP, GITHUB_PROFILE_URL, true);
		addLink(links, GITHUB_16, GITHUB_TIP, pluginGitHubUrl, true);
		links.add(Box.createHorizontalGlue());
		return links;
	}

	/** One mark of {@link #linksRow}, after {@link #LINK_GAP} px of clear ground unless it is the first. */
	private void addLink(JPanel links, String resource, String name, String url, boolean gapBefore)
	{
		final JLabel mark = namedIconButton(markIcon(resource, MARK_REST_ALPHA), markIcon(resource, 1f), name, () ->
		{
			browser.accept(url);
			closeMenu.run();
		});
		if (gapBefore)
		{
			links.add(Box.createHorizontalStrut(LINK_GAP));
		}
		links.add(mark);
	}

	/**
	 * One brand mark: {@code resource} at the settings icon's grey by alpha at rest ({@link #MARK_REST_ALPHA}) and at
	 * full white under the mouse, {@code name} for an always-on hover, and a LEFT press hands {@code url} to the
	 * browser.
	 */
	private JLabel brandMark(String resource, String name, String url)
	{
		return namedIconButton(markIcon(resource, MARK_REST_ALPHA), markIcon(resource, 1f), name,
			() -> browser.accept(url));
	}

	/**
	 * The border a card's settings icon and the Discord mark beside it share: 2 px above and below and, on the
	 * left, the 6 px of hit area on the side the pointer arrives from - a 12 px glyph is a 12 px target otherwise,
	 * and a settings button is not a decoration.
	 */
	static Border iconBorder()
	{
		return new EmptyBorder(2, INSET, 2, 0);
	}

	/**
	 * An icon-only control that names itself: {@link #pressable}'s look and press, with a ONE-WORD hover that is
	 * always on, like every hover in a 2hBuilds plugin. The word is set on the label directly: there is no hover
	 * switch for it to be offered to.
	 */
	static JLabel namedIconButton(ImageIcon rest, ImageIcon hot, String name, Runnable onClick)
	{
		final JLabel label = pressable(rest, hot, onClick);
		label.setToolTipText(name);
		return label;
	}

	/**
	 * The look and the press of an icon button, with no hover yet: {@code rest} at rest, {@code hot} while the mouse is
	 * over it, a hand cursor, and a LEFT press runs {@code onClick} - a right-button press is a menu gesture
	 * everywhere in a sidebar, never a press, and so is a ctrl-click of the left button on macOS.
	 */
	static JLabel pressable(ImageIcon rest, ImageIcon hot, Runnable onClick)
	{
		final JLabel label = new JLabel(rest);
		label.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		label.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e) && !e.isPopupTrigger())
				{
					onClick.run();
				}
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				label.setIcon(hot);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				label.setIcon(rest);
			}
		});
		return label;
	}

	/**
	 * A brand's own mark, loaded from the classpath and never redrawn: the Discord symbol, the X logo and GitHub's
	 * Invertocat are white on transparent PNGs in this package's resource folder, resized and nothing else, because
	 * the brands allow white and none allows a mark drawn by somebody else. Loaded with RuneLite's
	 * {@link ImageUtil#loadImageResource} - the ordinary plugin way; a classpath resource is not file I/O - and each
	 * file ONCE, however many icons are made from it.
	 *
	 * <p>The look is chosen by {@code alpha}, never by recolouring: at 1 the mark is the file as it is (white), and
	 * below 1 {@link ImageUtil#alphaOffset(java.awt.Image, float)} scales only the alpha, so a white mark at
	 * {@link #MARK_REST_ALPHA} reads on the card as the settings icon's grey.
	 *
	 * @param resource a file name in this class's package's resource folder, e.g. {@code "discord_12.png"}
	 * @param alpha    1 for the mark at full white, less for it fainter
	 */
	static ImageIcon markIcon(String resource, float alpha)
	{
		final BufferedImage mark = MARKS.computeIfAbsent(resource,
			r -> ImageUtil.loadImageResource(SupportLinks.class, r));
		return new ImageIcon(alpha >= 1f ? mark : ImageUtil.alphaOffset(mark, alpha));
	}

	/** The Swing sans at {@code size} px: RuneLite's default font, derived, so the shared constant is never mutated. */
	private static Font sans(int size)
	{
		return FontManager.getDefaultFont().deriveFont((float) size);
	}

	/** The bold Swing sans at {@code size} px. */
	private static Font sansBold(int size)
	{
		return FontManager.getDefaultBoldFont().deriveFont((float) size);
	}

	/** A label with its font and colour set explicitly, never left to the look and feel. */
	private static JLabel label(String text, Font font, Color colour)
	{
		final JLabel label = new JLabel(text);
		label.setFont(font);
		label.setForeground(colour);
		return label;
	}
}

