package com.crowdalarm;

import net.runelite.client.config.FlashNotification;
import net.runelite.client.config.Notification;
import net.runelite.client.config.NotificationSound;
import net.runelite.client.config.RequestFocusType;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * T25: RuneLite's notification built from the Sound tick. It is always enabled, marked override and initialized (or
 * RuneLite would use its own global settings instead), sent while the game window is in front, never a second chat
 * line, a pop-up, a focus grab or RuneLite's own flash (the plugin draws its own). The sound is RuneLite's own alert
 * sound ("custom" with no sound name: the player's notification.wav or RuneLite's), not the system beep, which was
 * silent for the owner.
 */
public class AlertSignalTest
{
	private static void expectTheBase(Notification notification)
	{
		assertTrue("enabled", notification.isEnabled());
		assertTrue("initialized", notification.isInitialized());
		assertTrue("override", notification.isOverride());
		assertTrue("sent while the game window is in front", notification.isSendWhenFocused());
		assertFalse("no chat line of RuneLite's own", notification.isGameMessage());
		assertFalse("no desktop pop-up", notification.isTray());
		assertEquals(RequestFocusType.OFF, notification.getRequestFocus());
		assertEquals("RuneLite's flash stays off", FlashNotification.DISABLED, notification.getFlash());
		assertNotNull(notification.getTrayIconType());
	}

	@Test
	public void t25SoundOffStillReachesRuneLiteButIsSilent()
	{
		final Notification notification = AlertSignal.of(false);
		expectTheBase(notification);
		assertEquals(NotificationSound.OFF, notification.getSound());
	}

	@Test
	public void t25SoundIsRuneLitesOwnAlertSoundNotTheSystemBeep()
	{
		final Notification notification = AlertSignal.of(true);
		expectTheBase(notification);
		assertEquals(NotificationSound.CUSTOM, notification.getSound());
		assertNull("no sound name: the player's notification.wav or RuneLite's own", notification.getSoundName());
		assertEquals(AlertSignal.VOLUME, notification.getVolume());
		assertEquals(100, AlertSignal.VOLUME);
	}
}

