package com.crowdalarm;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.Arrays;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.CALLS_REAL_METHODS;
import static org.mockito.Mockito.doReturn;
import static org.mockito.Mockito.mock;

/**
 * The count box drawn for real onto an image: whether it shows, how tall it is, and the colour of its border. The
 * plugin is faked; the box's own rules are the ones under test. Unless a test says otherwise the config is the default
 * (Crowd size 20, "Gold border at crowd size" on, the arrival alarm off).
 */
public class CountOverlayRenderTest
{
	private static final Color GREEN = new Color(10, 200, 10);
	private static final Color BLUE = new Color(10, 10, 200);

	private CrowdAlarmPlugin plugin;
	private CrowdAlarmConfig config;
	private CountOverlay overlay;
	private BufferedImage image;
	private Dimension size;

	@Before
	public void setUp()
	{
		plugin = mock(CrowdAlarmPlugin.class);
		config = mock(CrowdAlarmConfig.class, CALLS_REAL_METHODS);
		overlay = new CountOverlay(plugin, config);
		doReturn(25).when(plugin).getShownCount();
		doReturn(-1).when(plugin).getShownArrived();
		doReturn(GREEN).when(config).borderAbove();
		doReturn(BLUE).when(config).borderBelow();
	}

	/**
	 * RuneLite's panel sizes its background from the frame before (a fresh box is 8 x 8 on its first draw and a changed
	 * one is a frame late), so a change is drawn twice to let it settle, as the next frame would in the game.
	 */
	private void draw()
	{
		render();
		render();
	}

	private void render()
	{
		image = new BufferedImage(240, 120, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D graphics = image.createGraphics();
		try
		{
			size = overlay.render(graphics);
		}
		finally
		{
			graphics.dispose();
		}
	}

	private Color cornerPixel()
	{
		return new Color(image.getRGB(1, 1), true);
	}

	@Test
	public void o1ItIsHiddenWhenSwitchedOffOrThereIsNothingToShow()
	{
		doReturn(false).when(config).showCount();
		draw();
		assertNull(size);

		doReturn(true).when(config).showCount();
		doReturn(-1).when(plugin).getShownCount();
		draw();
		assertNull("hidden where the plugin is off", size);
	}

	@Test
	public void o2ItShowsTheBoxWhenThereIsACount()
	{
		doReturn(0).when(plugin).getShownCount();
		draw();
		assertNotNull("a count of zero still shows", size);
		assertTrue(size.width > 0 && size.height > 0);
	}

	@Test
	public void o3WithTheBorderOffThereIsNoColouredBorder()
	{
		doReturn(false).when(config).crowdBorder();
		draw();
		assertNotEquals(GREEN, cornerPixel());
		doReturn(5).when(plugin).getShownCount();
		draw();
		assertNotEquals(BLUE, cornerPixel());
	}

	@Test
	public void o4TheBorderFollowsTheLiveCount()
	{
		draw();
		assertEquals("25 of 20", GREEN, cornerPixel());
		doReturn(20).when(plugin).getShownCount();
		draw();
		assertEquals("exactly at the target", GREEN, cornerPixel());
		doReturn(19).when(plugin).getShownCount();
		draw();
		assertEquals("one under", BLUE, cornerPixel());
		doReturn(21).when(plugin).getShownCount();
		draw();
		assertEquals("back over, at once", GREEN, cornerPixel());
