		doReturn(3).when(plugin).getShownArrived();
		doReturn(true).when(config).arrive();
		draw();
		assertTrue("a second line: plain=" + plain + " now=" + size.height, size.height > plain);

		doReturn(false).when(config).arrive();
		draw();
		assertEquals("not with the arrival alarm off (plain=" + plain + ")", plain, size.height);

		doReturn(true).when(config).arrive();
		doReturn(false).when(config).showProgress();
		draw();
		assertEquals("not when switched off", plain, size.height);

		doReturn(true).when(config).showProgress();
		doReturn(-1).when(plugin).getShownArrived();
