		doReturn(true).when(config).showProgress();
		doReturn(true).when(config).arrive();
		doReturn(3).when(plugin).getShownArrived();
		doReturn(7).when(config).arrivePlayers();
		draw();
		final int[] threeOfSeven = pixels();

		doReturn(8).when(config).arrivePlayers();
