package com.crowdalarm;

import java.util.HashSet;
import java.util.Set;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * T1 to T12: the frozen tests of {@link CrowdWatch}. T1 and T12 were changed at the owner's word on 2026-11-20: a
 * first tick (login, a hop, a counting setting changing) that finds the crowd already there now alerts once, where it
 * used to only record; the others are unchanged. Unless a test says otherwise: players 20, within 5 000 ms, cooldown
 * 30 000 ms, the player stood still. "n names" is a set of n different names, each set a superset of the smaller ones,
 * so growing from 5 to 11 names means 6 new players.
 */
public class CrowdWatchTest
{
	private static final int PLAYERS = 20;
	private static final long WITHIN = 5_000;
	private static final long COOLDOWN = 30_000;

	private final CrowdWatch watch = new CrowdWatch();

	private static Set<String> names(int n)
	{
		final Set<String> set = new HashSet<>();
		for (int i = 0; i < n; i++)
		{
			set.add("p" + i);
		}
		return set;
	}

	private int onScreen(int n, long t)
	{
		return watch.tick(names(n), true, t, AlertMode.ON_SCREEN, PLAYERS, WITHIN, COOLDOWN);
	}

	private int arrive(int n, long t, boolean stoodStill, int players, long cooldown)
	{
		return watch.tick(names(n), stoodStill, t, AlertMode.ARRIVE, players, WITHIN, cooldown);
	}

	@Test
	public void t1AFirstTickThatFindsTheCrowdAlreadyThereAlertsOnce()
	{
		assertEquals("the crowd is already there", 30, onScreen(30, 0));
		assertEquals("once: it stays, it does not climb", 0, onScreen(30, 600));

		final CrowdWatch below = new CrowdWatch();
		assertEquals("a first tick below the players only records", 0,
			below.tick(names(19), true, 0, AlertMode.ON_SCREEN, PLAYERS, WITHIN, COOLDOWN));

		final CrowdWatch arrival = new CrowdWatch();
		assertEquals("a first tick has seen no one arrive", 0,
			arrival.tick(names(30), true, 0, AlertMode.ARRIVE, PLAYERS, WITHIN, COOLDOWN));
	}

	@Test
	public void t2OnScreenAlertsWhenTheCountReachesThePlayers()
	{
		assertEquals(0, onScreen(5, 0));
		assertEquals(0, onScreen(19, 600));
		assertEquals(20, onScreen(20, 1_800));
		assertEquals(0, onScreen(25, 2_000));
	}

	@Test
	public void t3OnScreenAlertsAgainAfterDroppingBelowAndTheCooldown()
	{
		assertEquals(0, onScreen(5, 0));
		assertEquals(0, onScreen(19, 600));
		assertEquals(20, onScreen(20, 1_800));
		assertEquals(0, onScreen(25, 2_000));
		assertEquals(0, onScreen(10, 2_400));
		assertEquals(22, onScreen(22, 40_000));
	}

	@Test
	public void t4TheCooldownHoldsAnAlertBackButTheDropAndReturnStillCount()
	{
		assertEquals(0, onScreen(5, 0));
		assertEquals(25, onScreen(25, 600));
		assertEquals(0, onScreen(5, 1_200));
		assertEquals(0, onScreen(25, 10_000));
		assertEquals(0, onScreen(5, 10_600));
		assertEquals(25, onScreen(25, 31_000));
	}

	@Test
	public void t5ArrivalsWithinTheWindowAddUp()
	{
		assertEquals(0, arrive(1, 0, true, 10, COOLDOWN));
		assertEquals(0, arrive(5, 600, true, 10, COOLDOWN));
		assertEquals(10, arrive(11, 1_200, true, 10, COOLDOWN));
	}

	@Test
	public void t6ArrivalsOlderThanTheWindowAreDropped()
	{
		assertEquals(0, arrive(1, 0, true, 10, COOLDOWN));
		assertEquals(0, arrive(7, 600, true, 10, COOLDOWN));
		assertEquals(0, arrive(13, 6_000, true, 10, COOLDOWN));
	}

	@Test
	public void t7NewPlayersWhileMovingCountNothing()
	{
		assertEquals(0, arrive(1, 0, true, 10, COOLDOWN));
		assertEquals(0, arrive(13, 600, false, 10, COOLDOWN));
	}

	@Test
	public void t8MovingEmptiesTheWindow()
	{
		assertEquals(0, arrive(1, 0, true, 10, COOLDOWN));
		assertEquals(0, arrive(7, 600, true, 10, COOLDOWN));
		assertEquals(0, arrive(7, 1_200, false, 10, COOLDOWN));
		assertEquals(0, arrive(13, 1_800, true, 10, COOLDOWN));
	}

	@Test
	public void t9PlayersWhoLeaveAndComeBackAreArrivalsToo()
	{
		// First case: the return is 2 arrivals, below 3.
		assertEquals(0, arrive(5, 0, true, 3, COOLDOWN));
		assertEquals(0, arrive(5, 600, true, 3, COOLDOWN));
		assertEquals(0, arrive(5, 1_200, true, 3, COOLDOWN));
		assertEquals(0, arrive(5, 1_800, true, 3, COOLDOWN));
		assertEquals(0, arrive(3, 2_400, true, 3, COOLDOWN));
		assertEquals(0, arrive(5, 3_000, true, 3, COOLDOWN));

		// Second case: a new sixth name comes back with the two, 3 arrivals.
		final CrowdWatch second = new CrowdWatch();
		assertEquals(0, second.tick(names(5), true, 0, AlertMode.ARRIVE, 3, WITHIN, COOLDOWN));
		assertEquals(0, second.tick(names(5), true, 600, AlertMode.ARRIVE, 3, WITHIN, COOLDOWN));
		assertEquals(0, second.tick(names(5), true, 1_200, AlertMode.ARRIVE, 3, WITHIN, COOLDOWN));
		assertEquals(0, second.tick(names(5), true, 1_800, AlertMode.ARRIVE, 3, WITHIN, COOLDOWN));
		assertEquals(0, second.tick(names(3), true, 2_400, AlertMode.ARRIVE, 3, WITHIN, COOLDOWN));
		assertEquals(3, second.tick(names(6), true, 3_000, AlertMode.ARRIVE, 3, WITHIN, COOLDOWN));
	}

	@Test
	public void t10AnAlertEmptiesTheWindow()
	{
		assertEquals(0, arrive(1, 0, true, 10, 0));
		assertEquals(10, arrive(11, 600, true, 10, 0));
		assertEquals(0, arrive(14, 1_200, true, 10, 0));
	}

	@Test
	public void t11TheCooldownSwallowsASecondAlertButNotAThird()
	{
		assertEquals(0, arrive(1, 0, true, 5, COOLDOWN));
		assertEquals(5, arrive(6, 600, true, 5, COOLDOWN));
		assertEquals(0, arrive(11, 1_200, true, 5, COOLDOWN));
		assertEquals(5, arrive(16, 31_000, true, 5, COOLDOWN));
	}

	@Test
	public void t12ResetMakesTheNextTickAFirstTickAndKeepsTheCooldown()
	{
		assertEquals(0, onScreen(5, 0));
		watch.reset();
		assertEquals("a first tick again, the crowd already there", 50, onScreen(50, 600));
		assertEquals("only once", 0, onScreen(50, 1_200));
		watch.reset();
		assertEquals("the reset keeps the last alert's time", 0, onScreen(50, 1_800));
	}

	@Test
	public void t20TheCrowdLeavesWhenTheCountFallsBelowThePlayers()
	{
		assertEquals(0, onScreen(5, 0));
		assertFalse(watch.crowdLeft());
		assertEquals(25, onScreen(25, 600));
		assertFalse("arriving is not leaving", watch.crowdLeft());
		assertEquals(0, onScreen(22, 1_200));
		assertFalse("still above", watch.crowdLeft());
		assertEquals(0, onScreen(10, 1_800));
		assertTrue("fell below", watch.crowdLeft());
		assertEquals(0, onScreen(9, 2_400));
		assertFalse("only the tick it fell on", watch.crowdLeft());
	}

	@Test
	public void t20ACrowdThereAtTheFirstTickCanLeaveButTheFirstTickIsNotALeaving()
	{
		assertEquals(30, onScreen(30, 0));
		assertFalse(watch.crowdLeft());
		assertEquals(0, onScreen(10, 600));
		assertTrue(watch.crowdLeft());
	}

	@Test
	public void t20LeavingHasItsOwnCooldownAndArriveModeNeverReportsIt()
	{
		assertEquals(0, onScreen(5, 0));
		assertEquals(25, onScreen(25, 600));
		assertEquals(0, onScreen(10, 1_200));
		assertTrue(watch.crowdLeft());
		assertEquals(0, onScreen(25, 2_000));
		assertEquals(0, onScreen(10, 3_000));
		assertFalse("within the cooldown of the last leaving", watch.crowdLeft());
		assertEquals(25, onScreen(25, 40_000));
		assertEquals(0, onScreen(10, 41_000));
		assertTrue("after the cooldown", watch.crowdLeft());

		final CrowdWatch arrive = new CrowdWatch();
		arrive.tick(names(30), true, 0, AlertMode.ARRIVE, PLAYERS, WITHIN, COOLDOWN);
		arrive.tick(names(5), true, 600, AlertMode.ARRIVE, PLAYERS, WITHIN, COOLDOWN);
		assertFalse(arrive.crowdLeft());
	}

	@Test
	public void t20ResetForgetsALeaving()
	{
		assertEquals(30, onScreen(30, 0));
		assertEquals(0, onScreen(10, 600));
		assertTrue(watch.crowdLeft());
		watch.reset();
		assertFalse(watch.crowdLeft());
	}

	@Test
	public void t26ASettingChangeKeepsWhetherTheCrowdWasThere()
	{
		assertEquals(25, onScreen(25, 0));
		watch.settingsChanged();
		assertEquals("the crowd stayed: no second alert", 0, onScreen(25, 40_000));
		assertEquals(0, onScreen(25, 40_600));

		// The players go up over the crowd: nobody left, so no leaving.
		watch.settingsChanged();
		assertEquals(0, watch.tick(names(25), true, 41_200, AlertMode.ON_SCREEN, 30, WITHIN, COOLDOWN));
		assertFalse("raising the players is not the crowd leaving", watch.crowdLeft());

		// The players come back down under the crowd: that is the crowd being reached, after the cooldown.
		watch.settingsChanged();
		assertEquals(25, watch.tick(names(25), true, 80_000, AlertMode.ON_SCREEN, PLAYERS, WITHIN, COOLDOWN));
	}

	@Test
	public void t26ASettingChangeForgetsWhoWasThereForArrivals()
	{
		assertEquals(0, arrive(5, 0, true, 10, COOLDOWN));
		assertEquals(0, arrive(9, 600, true, 10, COOLDOWN));
		assertEquals(4, watch.arrivedSoFar());
		watch.settingsChanged();
		assertEquals("a wider area is not an arrival", 0, arrive(20, 1_200, true, 10, COOLDOWN));
		assertEquals(0, watch.arrivedSoFar());
	}

	@Test
	public void t21ArrivedSoFarIsWhatTheWindowHolds()
	{
		assertEquals(0, arrive(1, 0, true, 10, COOLDOWN));
		assertEquals(0, watch.arrivedSoFar());
		assertEquals(0, arrive(5, 600, true, 10, COOLDOWN));
		assertEquals(4, watch.arrivedSoFar());
		assertEquals(0, arrive(8, 1_200, true, 10, COOLDOWN));
		assertEquals(7, watch.arrivedSoFar());
		assertEquals(0, arrive(8, 7_000, true, 10, COOLDOWN));
		assertEquals("both are older than the window", 0, watch.arrivedSoFar());
		assertEquals(0, arrive(12, 7_600, true, 10, COOLDOWN));
		assertEquals(4, watch.arrivedSoFar());
		assertEquals(0, arrive(14, 8_200, false, 10, COOLDOWN));
		assertEquals("moving empties it", 0, watch.arrivedSoFar());
		assertEquals(0, arrive(15, 8_800, true, 10, COOLDOWN));
		assertEquals(1, watch.arrivedSoFar());
		assertEquals(10, arrive(24, 9_400, true, 10, COOLDOWN));
		assertEquals("an alert empties it", 0, watch.arrivedSoFar());
	}
}

package com.crowdalarm;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * T27: the "Flash the screen" pulse: two smooth gold pulses over 2 seconds, each the same, each starting and ending
 * clear, timed from the alert (RuneLite's own flash cut its first blink short, which the owner saw).
 */
public class FlashPulseTest
{
	@Test
	public void t27TwoPulsesThatStartAndEndClear()
	{
		assertEquals("before the alert", 0, FlashPulse.alpha(-1));
		assertEquals("starts clear", 0, FlashPulse.alpha(0));
		assertEquals("halfway up", 35, FlashPulse.alpha(250));
		assertEquals("the strongest", FlashPulse.MAX_ALPHA, FlashPulse.alpha(500));
		assertEquals("clear between the pulses", 0, FlashPulse.alpha(1_000));
		assertEquals("the second pulse at its strongest", FlashPulse.MAX_ALPHA, FlashPulse.alpha(1_500));
		assertEquals("ends clear", 0, FlashPulse.alpha(1_999));
		assertEquals("over", 0, FlashPulse.alpha(2_000));
		assertEquals("long over", 0, FlashPulse.alpha(60_000));
		assertEquals(2_000, FlashPulse.DURATION_MS);
		assertEquals(70, FlashPulse.MAX_ALPHA);
	}

	@Test
	public void t27BothPulsesAreTheSame()
	{
		for (long t = 0; t < FlashPulse.PULSE_MS; t += 25)
		{
			assertEquals("at " + t + " ms", FlashPulse.alpha(t), FlashPulse.alpha(t + FlashPulse.PULSE_MS));
		}
	}

	@Test
	public void t27NoJumpsFromOneFrameToTheNext()
	{
		// A frame is about 20 ms at 50 frames a second: the gold never changes by more than a few steps out of 255.
		for (long t = 0; t + 20 <= FlashPulse.DURATION_MS; t++)
		{
			final int step = Math.abs(FlashPulse.alpha(t + 20) - FlashPulse.alpha(t));
			assertTrue("at " + t + " ms the step is " + step, step <= 6);
		}
	}

	@Test
	public void t27EachPulseRisesThenFalls()
	{
		assertTrue(FlashPulse.alpha(100) < FlashPulse.alpha(300));
		assertTrue(FlashPulse.alpha(300) < FlashPulse.alpha(500));
		assertTrue(FlashPulse.alpha(500) > FlashPulse.alpha(700));
		assertTrue(FlashPulse.alpha(700) > FlashPulse.alpha(900));
	}
}

