/**
 * The plugin's wiring, with the client faked: what one game tick counts, when it alerts and tells the player, the
 * places it stays off, the settings that reset it, the two alarms with their own numbers and ticks and the one wait
 * they share, and the test alert. The pure rules are in the other tests; this checks that the plugin hands them the
 * right facts and acts on the answers. Unless a test says otherwise the config is Crowd size 3, no wait between
 * alerts, the sudden crowd alert off (Players arriving at its default, 10) and everything else at its default.
 */
@RunWith(MockitoJUnitRunner.Silent.class)
public class PluginWiringTest
{
	@Mock
	private Client client;
	@Mock
	private ClientThread clientThread;
	@Mock
	private Notifier notifier;
	@Mock
	private OverlayManager overlayManager;
	@Mock
	private CountOverlay countOverlay;
	@Mock
	private RangeOverlay rangeOverlay;
	@Mock
	private ScreenFlashOverlay flashOverlay;
	@Mock
	private ConfigManager configManager;
	@Mock(answer = Answers.CALLS_REAL_METHODS)
	private CrowdAlarmConfig config;
	@Mock
	private Player local;
	@Mock
	private WorldView view;
	@Mock
	private IndexedObjectSet<Player> players;

	@InjectMocks
	private CrowdAlarmPlugin plugin;

	private final List<Player> others = new ArrayList<>();
	private WorldPoint here = new WorldPoint(3000, 3000, 0);

	@Before
	public void setUp()
	{
		// The real local player has a name and is in the client's player list: only the plugin's own check keeps it out.
		when(local.getName()).thenReturn("me");
		when(local.getWorldLocation()).thenAnswer(call -> here);
		when(client.getLocalPlayer()).thenReturn(local);
		when(client.getTopLevelWorldView()).thenReturn(view);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getWorldType()).thenReturn(EnumSet.noneOf(WorldType.class));
		doReturn(players).when(view).players();
		when(players.iterator()).thenAnswer(call ->
		{
			final List<Player> all = new ArrayList<>();
			all.add(local);
			all.addAll(others);
			return all.iterator();
		});
		doAnswer(call ->
		{
			((Runnable) call.getArgument(0)).run();
			return null;
		}).when(clientThread).invoke(any(Runnable.class));
		doReturn(3).when(config).players();
		doReturn(0).when(config).cooldownSeconds();
	}

	private Player addPlayer(String name, int dx, int dy, int plane, boolean friend, boolean clan)
	{
		final Player player = mock(Player.class);
		when(player.getName()).thenReturn(name);
		when(player.getWorldLocation()).thenReturn(new WorldPoint(3000 + dx, 3000 + dy, plane));
		when(player.isFriend()).thenReturn(friend);
		when(player.isClanMember()).thenReturn(clan);
		others.add(player);
		return player;
	}

	private void addCrowd(int n)
	{
		for (int i = 0; i < n; i++)
