	private void tick()
	{
		plugin.onGameTick(new GameTick());
	}

	/** RuneLite's notification was handed this text (the notification itself is checked in w19 and T25). */
	private void verifyAlert(String text)
	{
		verify(notifier).notify(any(Notification.class), eq(text));
	}

	private void configChanged(String key, String newValue)
	{
		final ConfigChanged event = new ConfigChanged();
		event.setGroup(CrowdAlarmConfig.GROUP);
		event.setKey(key);
		event.setNewValue(newValue);
		plugin.onConfigChanged(event);
	}

