	@Test
	public void w19TheSoundAndFlashTicksReachTheAlertAndAreOffByDefault()
	{
		final ArgumentCaptor<Notification> sent = ArgumentCaptor.forClass(Notification.class);
		addCrowd(2);
		tick();
		addPlayer("late", 2, 2, 0, false, false);
		tick();
		verify(notifier).notify(sent.capture(), eq("2h Crowd Alarm: crowd size reached, 3 players nearby."));
		assertEquals("sound off by default", NotificationSound.OFF, sent.getValue().getSound());
		assertEquals("no flash by default", 0, plugin.getFlashStartMs());
		assertEquals("never RuneLite's own flash", FlashNotification.DISABLED, sent.getValue().getFlash());
		assertFalse("never a pop-up", sent.getValue().isTray());
		assertTrue("sent while the game window is in front", sent.getValue().isSendWhenFocused());

		// Each tick reaches its own part: the sound without the flash, then the flash without the sound.
		doReturn(true).when(config).sound();
		configChanged("testAlert", "true");
		verify(notifier, times(2)).notify(sent.capture(), anyString());
		assertEquals("RuneLite's own alert sound", NotificationSound.CUSTOM, sent.getValue().getSound());
		assertEquals("still no flash", 0, plugin.getFlashStartMs());

		doReturn(false).when(config).sound();
		doReturn(true).when(config).flash();
		final long before = System.currentTimeMillis();
		configChanged("testAlert", "true");
		verify(notifier, times(3)).notify(sent.capture(), anyString());
		assertEquals(NotificationSound.OFF, sent.getValue().getSound());
		assertTrue("the flash starts now", plugin.getFlashStartMs() >= before);
		assertEquals("still never RuneLite's own flash", FlashNotification.DISABLED, sent.getValue().getFlash());
	}

