package com.crowdalarm;

import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/** T17 and T18: the search-area line's fade and its outline. */
public class RangeLineTest
{
	@Test
	public void t17TheLineFadesOverThreeSeconds()
	{
		assertEquals(255, RangeFade.alpha(0));
		assertEquals(128, RangeFade.alpha(1_500));
		assertTrue("still showing just before the end", RangeFade.alpha(2_999) > 0);
		assertEquals(0, RangeFade.alpha(3_000));
		assertEquals(0, RangeFade.alpha(60_000));
		assertEquals("a clock set backwards shows nothing", 0, RangeFade.alpha(-1));
		int previous = 256;
		for (long t = 0; t < 3_000; t += 50)
		{
			final int now = RangeFade.alpha(t);
			assertTrue("never gets brighter", now <= previous);
			previous = now;
		}
	}

	@Test
	public void t18TheOutlineIsAClosedSquareAtTheEdgeOfTheArea()
	{
		for (int distance : new int[]{1, 2, 5, 15})
		{
			final List<int[]> loop = RangeOutline.loop(distance);
			final int edge = distance * RangeOutline.TILE + RangeOutline.TILE / 2;
			assertEquals(4 * (2 * distance + 1) + 1, loop.size());
			assertEquals("closed", loop.get(0)[0], loop.get(loop.size() - 1)[0]);
			assertEquals("closed", loop.get(0)[1], loop.get(loop.size() - 1)[1]);
			for (int i = 0; i < loop.size(); i++)
			{
				final int[] p = loop.get(i);
				assertEquals("on the edge", edge, Math.max(Math.abs(p[0]), Math.abs(p[1])));
				if (i > 0)
				{
					final int[] q = loop.get(i - 1);
					assertEquals("one tile apart", RangeOutline.TILE, Math.abs(p[0] - q[0]) + Math.abs(p[1] - q[1]));
				}
			}
		}
	}
}

