import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.CALLS_REAL_METHODS;
import static org.mockito.Mockito.doReturn;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * The screen flash drawn for real onto an image the size of the game screen: nothing before an alert, see-through
 * colour over the whole screen halfway through a pulse (gold by default, else the "Flash colour" picked), nothing once
 * the 2 seconds are over. The plugin and the client are faked; the settings are the real defaults unless a test says.
 */
public class ScreenFlashRenderTest
{
	private static final int WIDTH = 200;
	private static final int HEIGHT = 100;

	private CrowdAlarmPlugin plugin;
	private CrowdAlarmConfig config;
	private ScreenFlashOverlay overlay;
	private BufferedImage image;

	@Before
	public void setUp()
	{
		plugin = mock(CrowdAlarmPlugin.class);
		config = mock(CrowdAlarmConfig.class, CALLS_REAL_METHODS);
		final Client client = mock(Client.class);
		when(client.getCanvasWidth()).thenReturn(WIDTH);
		when(client.getCanvasHeight()).thenReturn(HEIGHT);
		overlay = new ScreenFlashOverlay(client, plugin, config);
	}

	private void draw()
	{
		image = new BufferedImage(WIDTH, HEIGHT, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D graphics = image.createGraphics();
		try
		{
			overlay.render(graphics);
		}
		finally
		{
			graphics.dispose();
		}
	}

	private Color pixel(int x, int y)
	{
		return new Color(image.getRGB(x, y), true);
	}

	@Test
	public void f1NothingBeforeAnyAlert()
	{
		doReturn(0L).when(plugin).getFlashStartMs();
		draw();
		assertEquals(0, pixel(WIDTH / 2, HEIGHT / 2).getAlpha());
	}

	@Test
	public void f2HalfwayThroughAPulseTheWholeScreenIsSeeThroughGold()
	{
		doReturn(System.currentTimeMillis() - 500).when(plugin).getFlashStartMs();
		draw();
		for (int[] at : new int[][]{{0, 0}, {WIDTH / 2, HEIGHT / 2}, {WIDTH - 1, HEIGHT - 1}})
		{
			final Color colour = pixel(at[0], at[1]);
			assertTrue("see-through at " + at[0] + "," + at[1] + ": " + colour.getAlpha(),
				colour.getAlpha() >= 60 && colour.getAlpha() <= FlashPulse.MAX_ALPHA);
			assertTrue("gold at " + at[0] + "," + at[1] + ": " + colour,
				Math.abs(colour.getRed() - 196) <= 4 && Math.abs(colour.getGreen() - 156) <= 4
					&& Math.abs(colour.getBlue() - 58) <= 4);
		}
	}

	@Test
	public void f3NothingOnceTheTwoSecondsAreOver()
	{
		doReturn(System.currentTimeMillis() - 2_100).when(plugin).getFlashStartMs();
		draw();
		assertEquals(0, pixel(WIDTH / 2, HEIGHT / 2).getAlpha());
	}

	@Test
	public void f4TheFlashIsTheColourPickedAndStillSeeThrough()
	{
		doReturn(new Color(40, 90, 220)).when(config).flashColour();
		doReturn(System.currentTimeMillis() - 500).when(plugin).getFlashStartMs();
		draw();
		for (int[] at : new int[][]{{0, 0}, {WIDTH / 2, HEIGHT / 2}, {WIDTH - 1, HEIGHT - 1}})
		{
			final Color colour = pixel(at[0], at[1]);
			assertTrue("see-through at " + at[0] + "," + at[1] + ": " + colour.getAlpha(),
				colour.getAlpha() >= 60 && colour.getAlpha() <= FlashPulse.MAX_ALPHA);
			assertTrue("the colour picked at " + at[0] + "," + at[1] + ": " + colour,
				Math.abs(colour.getRed() - 40) <= 4 && Math.abs(colour.getGreen() - 90) <= 4
					&& Math.abs(colour.getBlue() - 220) <= 4);
		}
	}
}

